from dataclasses import dataclass, field
from mashumaro import DataClassDictMixin, field_options
from mashumaro.config import BaseConfig
@dataclass
class C(DataClassDictMixin):
 x:int=field(metadata=field_options(alias='xx'))
 class Config(BaseConfig): forbid_extra_keys=True
@dataclass
class P(DataClassDictMixin):
 c:C=field(metadata=field_options(flatten=True))
p=P(C(1)); print(p.to_dict(), P.from_dict(p.to_dict()))
@dataclass
class A(DataClassDictMixin):
 c:C=field(metadata=field_options(flatten=True,flatten_prefix='p_'))
@dataclass
class B(DataClassDictMixin):
 a:A=field(metadata=field_options(flatten=True,flatten_prefix='q_'))
b=B(A(C(2))); print(b.to_dict(), B.from_dict(b.to_dict()))
